func halve(price int) int {
    return price / 2
}

func apply(price int, rule func(int) int) int {
    return rule(price)
}

func main() {
    fmt.Println(apply(80, halve))
    fmt.Println(apply(80, func(p int) int {
        return p - 10
    }))
}

func run(op func(int, int) int) {
    if op == nil {
        fmt.Println("no operation")
        return
    }
    fmt.Println(op(2, 3))
}

func main() {
    var op func(int, int) int
    run(op)

    op = func(a, b int) int { return a + b }
    run(op)
}

